import { connection } from 'next/server'

export default async function UserDashboard() {
  // Preferences are user-specific and change per request, so wait for an
  // incoming request instead of letting this run during prerendering.
  await connection()

  let preferences: Record<string, unknown>
  try {
    const res = await fetch('https://api.example.com/user/preferences')
    if (!res.ok) {
      throw new Error(`Failed to fetch preferences: ${res.status}`)
    }
    preferences = await res.json()
  } catch {
    return (
      <div>
        <h2>User Dashboard</h2>
        <p>Unable to load your preferences right now.</p>
      </div>
    )
  }

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        {Object.entries(preferences).map(([key, value]) => (
          <li key={key}>
            {key}: {String(value)}
          </li>
        ))}
      </ul>
    </div>
  )
}

